<script>(()=>{const e=document.querySelector('[data-page-block-editor]');if(!e)return;const c=e.querySelector('[data-canvas]'),i=e.querySelector('[data-inspector]'),out=e.querySelector('[data-page-block-input]'),title=e.querySelector('[data-title-preview]'),titleInput=e.querySelector('[name=title]'),media=@json($mediaAssets->map(fn ($asset) => ['url' => $asset->provider_key, 'label' => $asset->title])->values());let b=JSON.parse(e.dataset.blocks||'[]'),selected=0,history=[],future=[];const d={hero:{eyebrow:'WELCOME',title:'A place to belong',body:'Share the invitation people should see first.',button_label:'Plan your visit',button_url:''},heading:{text:'A meaningful heading'},paragraph:{text:'Write a clear paragraph that helps people understand your ministry.'},image:{url:'',alt:'',caption:''},gallery:{images:'',columns:'three',caption:''},video_embed:{url:'',title:'A message to watch',caption:'Paste a YouTube or Vimeo link.'},audio:{url:'',title:'Listen now',caption:''},file:{url:'',label:'Download resource',description:''},media_text:{media_url:'',media_alt:'',placement:'left',title:'A message beside your media',body:'Use this layout to combine a visual with a clear invitation.',button_label:'Learn more',button_url:''},list:{title:'What to expect',items:'A warm welcome\nHelpful information\nA clear next step',ordered:'no'},accordion:{title:'Frequently asked questions',question_one:'What should I expect?',answer_one:'Add a helpful, reassuring answer.',question_two:'Where do I park?',answer_two:'Share the practical details visitors need.',question_three:'Is there something for children?',answer_three:'Explain the ministry options available.'},spacer:{height:'medium'},quote:{text:'A short quote or testimony.',attribution:''},call_to_action:{title:'Take your next step',body:'Give people a clear way to respond.',button_label:'Get connected',button_url:''},service_times:{title:'Join us this week',body:'Add a helpful invitation alongside your service times.'},events:{title:'What is happening next',body:'Share upcoming events and ways to get involved.'},groups:{title:'Find your community',body:'Invite people into groups and meaningful connection.'},section:{layout:'two',title:'A section with room to breathe',body:'Introduce the ideas in this part of the page.',column_one_title:'First column',column_one_body:'Use this space for a clear supporting thought.',column_two_title:'Second column',column_two_body:'Add another message or invitation.',column_three_title:'Third column',column_three_body:'Show this when you choose three columns.',background_color:'#F4F8F5',padding:'regular'},divider:{}};const n={hero:'Hero',heading:'Heading',paragraph:'Paragraph',image:'Image',quote:'Quote',call_to_action:'Call to action',service_times:'Service times',events:'Events',groups:'Groups',section:'Columns & section',media_text:'Media & text',gallery:'Gallery',video_embed:'Video embed',audio:'Audio',file:'File download',list:'List',accordion:'Accordion',spacer:'Spacer',divider:'Divider'};const esc=v=>String(v??'').replace(/[&<>'"]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[x]));const save=()=>out.value=JSON.stringify(b),snap=()=>{history.push(JSON.stringify(b));future=[];syncHistory()};const syncHistory=()=>{e.querySelector('[data-undo]').disabled=!history.length;e.querySelector('[data-redo]').disabled=!future.length};const block=x=>{let z=x.data||{};if(x.type==='hero')return `<div class="page-canvas-hero"><small>${esc(z.eyebrow)}</small><h1>${esc(z.title)}</h1><p>${esc(z.body)}</p><b>${esc(z.button_label)}</b></div>`;if(x.type==='section'){let columns=['one','two','three'].indexOf(z.layout)+1;return `<section class="page-canvas-section page-columns-${esc(z.layout)} page-padding-${esc(z.padding)}" style="background:${esc(z.background_color)}"><h2>${esc(z.title)}</h2><p>${esc(z.body)}</p><div class="page-canvas-columns">${[1,2,3].slice(0,columns).map(k=>`<div><h3>${esc(z[['','one','two','three'][k]+'_title'])}</h3><p>${esc(z[['','one','two','three'][k]+'_body'])}</p></div>`).join('')}</div></section>`}if(x.type==='heading')return `<h2>${esc(z.text)}</h2>`;if(x.type==='paragraph')return `<p>${esc(z.text)}</p>`;if(x.type==='image')return z.url?`<img src="${esc(z.url)}" alt="${esc(z.alt)}">`:'<div class="page-canvas-image-placeholder">Image</div>';if(x.type==='gallery'){let imgs=String(z.images||'').split(/\n+/).filter(Boolean);return imgs.length?`<div class="page-canvas-gallery page-gallery-${esc(z.columns)}">${imgs.map(url=>`<img src="${esc(url.trim())}" alt="">`).join('')}</div>`:'<div class="page-canvas-image-placeholder">Add image links to build a gallery</div>'}if(x.type==='video_embed')return `<div class="page-canvas-video"><b>VIDEO EMBED</b><strong>${esc(z.title)}</strong><small>${esc(z.url||'Paste a YouTube or Vimeo link')}</small></div>`;if(x.type==='audio')return `<div class="page-canvas-audio"><b>AUDIO</b><strong>${esc(z.title)}</strong><small>${esc(z.url||'Paste an audio file URL')}</small></div>`;if(x.type==='file')return `<div class="page-canvas-file"><b>FILE</b><strong>${esc(z.label)}</strong><small>${esc(z.description)}</small></div>`;if(x.type==='media_text')return `<div class="page-canvas-media-text page-media-${esc(z.placement)}"><div class="page-canvas-image-placeholder">${z.media_url?`Media selected`:'Image or video'}</div><div><h2>${esc(z.title)}</h2><p>${esc(z.body)}</p><b>${esc(z.button_label)}</b></div></div>`;if(x.type==='list'){let items=String(z.items||'').split(/\n+/).filter(Boolean);return `<div class="page-canvas-list"><h2>${esc(z.title)}</h2><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`}if(x.type==='accordion')return `<div class="page-canvas-accordion"><h2>${esc(z.title)}</h2>${['one','two','three'].map(key=>`<div><strong>${esc(z['question_'+key])}</strong><p>${esc(z['answer_'+key])}</p></div>`).join('')}</div>`;if(x.type==='spacer')return `<div class="page-canvas-spacer page-spacer-${esc(z.height)}">Spacer</div>`;if(x.type==='quote')return `<blockquote>“${esc(z.text)}”<small>${esc(z.attribution)}</small></blockquote>`;if(x.type==='call_to_action')return `<div class="page-canvas-cta"><h2>${esc(z.title)}</h2><p>${esc(z.body)}</p><b>${esc(z.button_label)}</b></div>`;if(['service_times','events','groups'].includes(x.type))return `<div class="page-canvas-module"><small>${n[x.type].toUpperCase()}</small><h2>${esc(z.title)}</h2><p>${esc(z.body)}</p></div>`;return '<hr>'};const field=(key,value,type)=>{let label=key.replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());if(key==='layout')return `<label>${label}<select data-field="${key}"><option value="one" ${value==='one'?'selected':''}>One column</option><option value="two" ${value==='two'?'selected':''}>Two columns</option><option value="three" ${value==='three'?'selected':''}>Three columns</option></select></label>`;if(key==='padding')return `<label>${label}<select data-field="${key}"><option value="compact" ${value==='compact'?'selected':''}>Compact</option><option value="regular" ${value==='regular'?'selected':''}>Regular</option><option value="spacious" ${value==='spacious'?'selected':''}>Spacious</option></select></label>`;if(key==='columns')return `<label>Gallery columns<select data-field="columns"><option value="two" ${value==='two'?'selected':''}>Two columns</option><option value="three" ${value==='three'?'selected':''}>Three columns</option><option value="four" ${value==='four'?'selected':''}>Four columns</option></select></label>`;if(key==='placement')return `<label>Media placement<select data-field="placement"><option value="left" ${value==='left'?'selected':''}>Media left</option><option value="right" ${value==='right'?'selected':''}>Media right</option></select></label>`;if(key==='ordered')return `<label>List style<select data-field="ordered"><option value="no" ${value==='no'?'selected':''}>Bulleted list</option><option value="yes" ${value==='yes'?'selected':''}>Numbered list</option></select></label>`;if(key==='height')return `<label>Spacer height<select data-field="height"><option value="small" ${value==='small'?'selected':''}>Small</option><option value="medium" ${value==='medium'?'selected':''}>Medium</option><option value="large" ${value==='large'?'selected':''}>Large</option></select></label>`;if(key==='background_color')return `<label>${label}<div class="page-colour-control"><input type="color" data-colour value="${esc(value||'#F4F8F5')}"><input data-field="${key}" value="${esc(value)}"></div></label>`;if(key==='url'){let label=type==='video_embed'?'Video link':type==='audio'?'Audio file link':type==='file'?'Download file link':'Image source';return `<label>${label}${type==='image'&&media.length?`<select data-media><option value="">Choose from media library</option>${media.map(a=>`<option value="${esc(a.url)}" ${a.url===value?'selected':''}>${esc(a.label)}</option>`).join('')}</select>`:''}<input data-field="url" value="${esc(value)}" placeholder="https://…"></label>`}if(key==='media_url')return `<label>Media link<input data-field="media_url" value="${esc(value)}" placeholder="https://…"></label>`;let multi=['body','text','caption','images','items','description','answer_one','answer_two','answer_three'].includes(key);return `<label>${label}${multi?`<textarea data-field="${key}">${esc(value)}</textarea>`:`<input data-field="${key}" value="${esc(value)}">`}</label>`};const render=()=>{save();c.innerHTML=b.map((x,k)=>`<article class="page-canvas-block ${k===selected?'is-selected':''}" data-index="${k}" draggable="true"><header><span>${String(k+1).padStart(2,'0')}</span><strong>${n[x.type]}</strong><em>Drag to reorder</em></header><div class="page-canvas-block-content">${block(x)}</div></article>`).join('');let x=b[selected];i.innerHTML=x?`<div class="page-inspector-selected"><span>${n[x.type]} block</span><strong>Content and appearance</strong></div>${Object.entries(x.data).map(([k,v])=>field(k,v,x.type)).join('')}<div class="page-inspector-actions"><button type="button" data-move="up" aria-label="Move block up" title="Move up"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m18 15-6-6-6 6"/></svg></button><button type="button" data-move="down" aria-label="Move block down" title="Move down"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><button type="button" data-duplicate aria-label="Duplicate block" title="Duplicate"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="11" rx="1"/><path d="M5 16V5a1 1 0 0 1 1-1h10"/></svg></button><button type="button" data-remove class="is-danger" aria-label="Remove block" title="Remove"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6M14 11v6M9 7l1-3h4l1 3M6 7l1 13h10l1-13"/></svg></button></div>`:'<div class="page-inspector-empty">Choose a block.</div>'};e.querySelectorAll('[data-add]').forEach(q=>q.onclick=()=>{snap();b.splice(selected+1,0,{type:q.dataset.add,data:{...d[q.dataset.add]}});selected++;render()});let dragging=null;c.onclick=x=>{let q=x.target.closest('[data-index]');if(q){selected=+q.dataset.index;render()}};c.ondragstart=x=>{let q=x.target.closest('[data-index]');if(!q)return;dragging=+q.dataset.index;q.classList.add('is-dragging');x.dataTransfer.effectAllowed='move'};c.ondragover=x=>x.preventDefault();c.ondrop=x=>{x.preventDefault();let q=x.target.closest('[data-index]');if(q&&dragging!==null){let target=+q.dataset.index;if(target!==dragging){snap();let [item]=b.splice(dragging,1);b.splice(target,0,item);selected=target;render()}}dragging=null};c.ondragend=()=>{dragging=null;c.querySelectorAll('.is-dragging').forEach(q=>q.classList.remove('is-dragging'))};const change=x=>{if(x.target.dataset.colour){x.target.nextElementSibling.value=x.target.value;x.target.nextElementSibling.dispatchEvent(new Event('input',{bubbles:true}));return}if(x.target.dataset.media){let url=x.target.value;if(url){let input=i.querySelector('[data-field=url]');input.value=url;input.dispatchEvent(new Event('input',{bubbles:true}))}return}let k=x.target.dataset.field;if(k&&b[selected]){if(!x.target.dataset.changed){snap();x.target.dataset.changed='1'}b[selected].data[k]=x.target.value;save();let content=c.querySelector(`[data-index="${selected}"] .page-canvas-block-content`);if(content)content.innerHTML=block(b[selected]);if(['layout','padding','background_color'].includes(k))render()}};i.oninput=change;i.onchange=change;i.onclick=x=>{let q=x.target.closest('button');if(!q)return;if(q.dataset.remove!==undefined){snap();b.splice(selected,1);selected=Math.max(0,selected-1);render()}if(q.dataset.duplicate!==undefined){snap();b.splice(selected+1,0,JSON.parse(JSON.stringify(b[selected])));selected++;render()}if(q.dataset.move){let next=q.dataset.move==='up'?selected-1:selected+1;if(next>=0&&next<b.length){snap();[b[selected],b[next]]=[b[next],b[selected]];selected=next;render()}}};e.querySelectorAll('[data-preview]').forEach(q=>q.onclick=()=>{e.querySelectorAll('[data-preview]').forEach(x=>x.classList.toggle('is-active',x===q));c.dataset.preview=q.dataset.preview});e.querySelector('[data-undo]').onclick=()=>{if(history.length){future.push(JSON.stringify(b));b=JSON.parse(history.pop());selected=Math.min(selected,b.length-1);render();syncHistory()}};e.querySelector('[data-redo]').onclick=()=>{if(future.length){history.push(JSON.stringify(b));b=JSON.parse(future.pop());render();syncHistory()}};titleInput.oninput=()=>title.textContent=titleInput.value||'Untitled page';e.onsubmit=save;render();syncHistory()})();</script>
